/* Pre-embedded sheet image assets (data URIs) so saved HTML and offline file:// views never lose images. */
(function(root,factory){
  const api=factory();
  if(typeof module==='object'&&module.exports)module.exports=api;
  else root.ToastFlowAssets=api;
})(typeof self!=='undefined'?self:this,function(){
  const ASSETS={"assets/tm-logo.png":"data:image/png;base64,","assets/nus-logo.png":"data:image/png;base64,","assets/paynow-qr.png":"data:image/png;base64,","assets/eventbrite-qr.png":"data:image/png;base64,","assets/menti-prepared.png":"data:image/png;base64,","assets/menti-tabletopics.png":"data:image/png;base64,","assets/menti-evaluator.png":"data:image/png;base64,","assets/location-map.png":"data:image/png;base64,","assets/location-map-scis2.png":"data:image/png;base64,"};
  const ALIASES={
    'assets/meetings/2026-09-11/location-map.png':'assets/location-map.png',
    'assets/meetings/2026-09-11/vote-prepared.png':'assets/menti-prepared.png',
    'assets/meetings/2026-09-11/vote-topics.png':'assets/menti-tabletopics.png',
    'assets/meetings/2026-09-11/vote-evaluator.png':'assets/menti-evaluator.png'
  };
  const BASENAMES={
    'tm-logo.png':'assets/tm-logo.png',
    'nus-logo.png':'assets/nus-logo.png',
    'paynow-qr.png':'assets/paynow-qr.png',
    'eventbrite-qr.png':'assets/eventbrite-qr.png',
    'menti-prepared.png':'assets/menti-prepared.png',
    'menti-tabletopics.png':'assets/menti-tabletopics.png',
    'menti-evaluator.png':'assets/menti-evaluator.png',
    'location-map.png':'assets/location-map.png',
    'location-map-scis2.png':'assets/location-map-scis2.png',
    'vote-prepared.png':'assets/menti-prepared.png',
    'vote-topics.png':'assets/menti-tabletopics.png',
    'vote-evaluator.png':'assets/menti-evaluator.png'
  };
  function keyOf(url){
    const s=String(url||'').split('#')[0].split('?')[0].replace(/\\/g,'/');
    if(!s||/^data:/i.test(s))return '';
    const idx=s.lastIndexOf('assets/');
    if(idx>=0)return s.slice(idx);
    const base=s.slice(s.lastIndexOf('/')+1);
    return BASENAMES[base]||s;
  }
  function resolve(url){
    const s=String(url||'');
    if(/^data:image\//i.test(s))return s;
    const k=keyOf(s);
    const mapped=ALIASES[k]||k;
    return ASSETS[mapped]||s;
  }
  return {ASSETS,resolve,keyOf};
});
